import hashlib,html,json,re
from pathlib import Path
root=Path(__file__).resolve().parents[2];out=root/'output/ui-review/visual-rhythm'
pairs=[]
for before in sorted(out.glob('before-*.png')):
 after=out/before.name.replace('before-','after-',1)
 if after.exists():pairs.append({'label':before.stem.removeprefix('before-'),'before':before.name,'after':after.name})
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Northstar UI 前后对比</title><style>body{margin:0;padding:24px;font:14px/1.7 system-ui;background:#f5f7fa;color:#192740}h1{font-size:24px;margin:0 0 8px}p{margin:0 0 16px;color:#5f7088}select{font:inherit;padding:8px;max-width:100%;margin-bottom:24px;border:1px solid #cbd5df;border-radius:8px}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}figure{margin:0;min-width:0}figcaption{font-weight:600;margin-bottom:12px}img{display:block;width:100%;height:auto;border:1px solid #e2e8f0;border-radius:8px;background:white}a{color:#087f70}@media(max-width:800px){.pair{grid-template-columns:1fr}}</style><h1>Northstar English · 间距与视觉节奏</h1><p>同一 Chrome、同一合成账户、同一视口；独立的 Before / After 生产构建。含顶部、主滚动区底部、概念卡局部与有数据状态。报告刷新时间及 Quiz 随机选项顺序不做逐像素相等要求。</p><label for="view">选择页面 / 状态 / 宽度（px） </label><select id="view"></select><div class="pair"><figure><figcaption>Before · 优化前 <a id="before-link" target="_blank">原图</a></figcaption><img id="before" alt="优化前真实页面截图"></figure><figure><figcaption>After · 优化后 <a id="after-link" target="_blank">原图</a></figcaption><img id="after" alt="优化后真实页面截图"></figure></div><script>const pairs=PAIRS;const select=document.querySelector('#view');for(const [i,p]of pairs.entries()){const o=new Option(p.label,i);select.add(o);if(p.label==='concepts-1440')o.selected=true;}function show(){const p=pairs[select.value];for(const side of ['before','after']){document.querySelector('#'+side).src=p[side];document.querySelector('#'+side+'-link').href=p[side];}}select.onchange=show;show();</script></html>'''
(out/'index.html').write_text(page.replace('PAIRS',json.dumps(pairs,ensure_ascii=False)))
(out/'screenshot-manifest.json').write_text(json.dumps({'pairs':len(pairs),'screenshots':[{ 'path':f.name,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()} for f in sorted(out.glob('*.png'))]},indent=2))
print(len(pairs),'paired screenshot views')
